/**
 * 「数列」ユニットの系列（数Ⅱ・B 第7章）。
 *
 * 背骨設計は docs/sequence_series_design.md（メイン Opus 5・2026-08-15）。
 * 系列1（お手本）はメインが実装し、系列2〜12 は並列委譲＋メイン検収（C15）。
 *
 * 出典: 池田洋介『数学Ⅱ・B 入門問題精講 改訂版』第7章 数列（旺文社）の
 * 章構成を借り、問題の値はすべてオリジナルに変更（copyright-credit-vs-copy）。
 *
 * ハブ胚細胞（背骨 §1）：
 *   数列は無限に続くのに、私たちが書けるのは有限の式と有限の手つきだけ。
 *   無限を捕まえる道は三つある——位置から値へ一足で跳ぶ式（一般項）、
 *   となりとの関係だけを言う式（漸化式）、一歩ぶんの保証だけで全部を覆う
 *   論法（帰納法）。そして無限個の足し算は、差の形に書き直せた瞬間に、
 *   中がすべて打ち消しあって両端だけが残る。
 *   ——数Ⅰ・A のハブ「帰着」の、離散の無限版。
 *
 * 入力の折り方（背骨 D2・入力系の拡張は不要）：
 * - 一般項の式そのものは答えさせない。「その式に大きな番号を入れた値」か
 *   「初項・公差・公比のどれか 1 つ」に折る（1 step 1 つ）
 * - 「第何項か」「初めて超える番号」は整数の檻
 * - 群数列の「第◯群の第◯項目」は順序対なので 1 問で答えさせない（別 step に割る）
 * - 証明（帰納法）は鎖の関節の数値を 1 step 1 関節
 * - 無理数も π も出ない。分数は既存の評価器でそのまま採点できる
 *
 * 値設計の掟（背骨 D3・この単元固有）：
 *   小さい番号を答えにすると、一般項を求めずに書き出すだけで当たってしまう。
 *   前半は「書き出せば解ける」土台に置き、山場は「書き出しでは到底届かない
 *   番号」に置く。項数の勘定（n か n−1 か）を間違えたら別の整数になる値を選ぶ。
 */

